SELECT

FROM environment_sandboxes
WHERE workspace_uuid = #{workspaceUUID}
AND environment_external_id = #{environmentExternalID}
AND work_external_id = #{workExternalID}
AND provider_sandbox_id IS NOT NULL
AND state IN ('creating', 'running', 'stopping')
ORDER BY created_at DESC, uuid DESC
LIMIT 1

mapper.update:
WITH recovery_target AS ( SELECT sandbox.uuid AS sandbox_uuid, work.uuid AS work_uuid FROM code_sessions code_session JOIN environment_work work ON work.organization_uuid = code_session.organization_uuid AND work.workspace_uuid = code_session.workspace_uuid AND work.environment_uuid = code_session.environment_uuid AND work.environment_external_id = code_session.environment_external_id AND work.session_uuid = code_session.session_uuid AND work.state = 'active' AND work.deleted_at IS NULL JOIN environment_sandboxes sandbox ON sandbox.organization_uuid = code_session.organization_uuid AND sandbox.workspace_uuid = code_session.workspace_uuid AND sandbox.environment_uuid = code_session.environment_uuid AND sandbox.work_uuid = work.uuid
AND sandbox.provider_sandbox_id = #{params.ProviderSandboxID}
AND ( sandbox.state = 'running' OR (sandbox.state = 'stopped' AND sandbox.stop_reason = 'idle_timeout' AND EXISTS (SELECT 1 FROM code_session_inbound_events e WHERE e.code_session_uuid = code_session.uuid AND e.deleted_at IS NULL AND e.delivery_status <> 'processed')) ) WHERE code_session.external_id = #{params.CodeSessionExternalID} AND code_session.status = 'active' AND code_session.worker_status IN ('idle', 'running', 'requires_action') AND code_session.deleted_at IS NULL AND EXISTS (SELECT 1 FROM sessions s WHERE s.uuid = code_session.session_uuid AND s.organization_uuid = code_session.organization_uuid AND s.workspace_uuid = code_session.workspace_uuid AND s.deleted_at IS NULL AND s.archived_at IS NULL AND s.status <> 'terminated') FOR UPDATE OF code_session, work, sandbox ), failed_sandbox AS ( UPDATE environment_sandboxes sandbox SET state = 'failed', last_error = #{params.LastError,sensitive=true}, stopped_at = COALESCE(stopped_at, NOW()), updated_at = NOW() FROM recovery_target target WHERE sandbox.uuid = target.sandbox_uuid RETURNING sandbox.uuid ) UPDATE environment_work work SET state = 'queued', claimed_by_worker_id = NULL, claim_expires_at = NULL, latest_heartbeat_at = NULL, heartbeat_ttl_seconds = NULL, updated_at = NOW() FROM recovery_target target WHERE work.uuid = target.work_uuid AND EXISTS (SELECT 1 FROM failed_sandbox)
